package ru.obr_mosmit.site.contact;import jakarta.persistence.*;
@Entity @Table(name="site_contacts") public class SiteContact{@Id private Long id=1L;private String city;private String address;@Column(name="public_email")private String publicEmail;@Column(name="public_email_note")private String publicEmailNote;@Column(name="chairman_role")private String chairmanRole;@Column(name="chairman_name")private String chairmanName;@Column(name="chairman_email")private String chairmanEmail;@Column(name="assistant_role")private String assistantRole;@Column(name="assistant_name")private String assistantName;@Column(name="assistant_email")private String assistantEmail;
public Long getId(){return id;}public String getCity(){return city;}public void setCity(String v){city=v;}public String getAddress(){return address;}public void setAddress(String v){address=v;}public String getPublicEmail(){return publicEmail;}public void setPublicEmail(String v){publicEmail=v;}public String getPublicEmailNote(){return publicEmailNote;}public void setPublicEmailNote(String v){publicEmailNote=v;}public String getChairmanRole(){return chairmanRole;}public void setChairmanRole(String v){chairmanRole=v;}public String getChairmanName(){return chairmanName;}public void setChairmanName(String v){chairmanName=v;}public String getChairmanEmail(){return chairmanEmail;}public void setChairmanEmail(String v){chairmanEmail=v;}public String getAssistantRole(){return assistantRole;}public void setAssistantRole(String v){assistantRole=v;}public String getAssistantName(){return assistantName;}public void setAssistantName(String v){assistantName=v;}public String getAssistantEmail(){return assistantEmail;}public void setAssistantEmail(String v){assistantEmail=v;}}
